// Dungeon Delver
// status: planned
// requires: engine: no commander
// requires: granted TriggerRule
// requires: what a rule on triggering asks of an ability
// Commander creatures you own have "Room abilities of dungeons you own trigger an additional time."
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); (planned_value!("engine: no commander", false => q.is_commander(affected)) && (*so_far).is(CardType::Creature) && Some(asker.controller) == Some(q.state().obj(affected).owner)) }
#[allow(unused_variables)] fn granted_0_trigger_rule(q: &dyn Query, asker: &Asker, event: &Event, triggering: &Triggering) -> bool { true && (planned_value!("what a rule on triggering asks of an ability", false => triggering.def.dungeon_room) && Some(asker.controller) == Some(triggering.controller)) && true }
#[allow(unused_variables)] fn ability_0_apply_0(q: &dyn LayerQuery, source: ObjectId, chars: &mut Chars) { let asker = &Asker::new(source, q.controller(source)); let card = { let o = q.state().obj(asker.source); o.copied_card().unwrap_or(o.card) }; let _ = card; if let Some(slot) = chars.abilities.iter().position(|a| a.is_none()) { chars.abilities[slot] = Some(planned_value!("granted TriggerRule", AbilityRef::delayed({ let o = q.state().obj(asker.source); o.copied_card().unwrap_or(o.card) }, 0) => AbilityRef::granted_static({ let o = q.state().obj(asker.source); o.copied_card().unwrap_or(o.card) }, 0))); } }
planned_item!("granted-trigger-rule" => granted_rules: CardDef { keywords: Keywords::of(&[]), abilities: &[], statics: &[], replacements: &[], preventions: &[], block_rules: &[], block_requirements: &[], attack_rules: &[], untap_bans: &[], enters: None, additional_triggers: &[granted_0_trigger_rule], ..CardDef::BLANK });

